const pick = (...names) => { for (const n of names) { try { return $(n); } catch (e) {} } throw new Error('Node not found: ' + names.join(' / ')); };
const norm = v => String(v || '').toLowerCase().replace(/\b(mr|mrs|ms|miss|dr|prof)\.?\s+/g, '').replace(/\s+/g, ' ').trim();
const findLead = (q, leads) => { q = norm(q); if (!q) return null;
  return leads.find(l => norm(l.id) === q) ||
         leads.find(l => l.profile_url && (norm(l.profile_url) === q || q.includes(norm(l.profile_url)))) ||
         leads.find(l => norm(l.name) === q) ||
         leads.find(l => l.name && (q.includes(norm(l.name)) || norm(l.name).includes(q))) || null; };
// Works whatever the form labels are: the conversation is the field named chat/conversation/message (or the longest text);
// the lead is found from any other field (lead id, name or profile link).
const s = pick('M: Get Settings').first().json;
if (String(s.paused).trim().toUpperCase() === 'TRUE') return [];
const fields = Object.entries($input.first().json).filter(([k, v]) => typeof v === 'string' && v.trim() && !/submittedAt|formMode/i.test(k));
const chatField = fields.find(([k]) => /conversation|chat|message/i.test(k)) || [...fields].sort((a, b) => b[1].length - a[1].length)[0] || ['', ''];
const chat = String(chatField[1]).trim();
const leads = pick('M: Get Leads').all().map(i => i.json).filter(l => l.id);
let lead = null, typed = '';
for (const [k, v] of fields) { if (k === chatField[0]) continue; typed = typed || v; lead = lead || findLead(v, leads); }
lead = lead || {};
return [{ json: {
  lead_id: lead.id || '', name: lead.name || typed, company: lead.company || '',
  profile_url: lead.profile_url || '', chat,
  prompt: `We are YOUR_COMPANY_NAME and we sell a learning management system (LMS). Below is our FULL LinkedIn conversation with ${lead.name || 'this person'}${lead.company ? ' (' + lead.company + ')' : ''}, oldest first.

${chat}

Read the WHOLE conversation and look at their latest message.
Classify it as exactly one of:
- stop: they said no, not interested, or asked us to stop / not contact them again
- needs_human: price disputes or negotiation, discounts, contracts, complaints, refunds, problems, angry tone, or they ask for a person / a call / a demo with someone
- normal: anything else
If normal, write OUR next reply: it must fit this exact conversation (refer to what they actually said), honest, no invented facts, prices or promises, max 500 characters, no pressure, and keep a clear way to say no.
Answer ONLY with JSON: {"category":"","reason":"max 12 words","reply":""}` } }];

const pick = (...names) => { for (const n of names) { try { return $(n); } catch (e) {} } throw new Error('Node not found: ' + names.join(' / ')); };
// AI result + keyword safety nets on THEIR latest message (stop > needs a person > normal)
const p = pick('M: Prepare').first().json;
const raw = String($input.first().json.output ?? '');
let d = {};
try { d = JSON.parse(raw.replace(/^\s*```(json)?/i, '').replace(/```\s*$/, '').trim()); } catch (e) { d = { category: 'needs_human', reason: 'AI output unreadable', reply: '' }; }
let cat = ['stop', 'needs_human', 'normal'].includes(d.category) ? d.category : 'needs_human';
let reason = d.reason || '';
// their latest message = last non-empty line that is not ours ("Us:" / "Me:" / "We:")
const lines = p.chat.split('\n').map(l => l.trim()).filter(Boolean);
const theirs = [...lines].reverse().find(l => !/^(us|me|we|our team)\s*:/i.test(l)) || lines[lines.length - 1] || '';
const last = theirs.toLowerCase();
if (/\b(stop|unsubscribe|not interested|no thanks|don'?t contact|do not contact|remove me|leave me alone)\b/.test(last)) {
  if (d.category !== 'stop') reason = 'said no / asked to stop'; cat = 'stop';
} else if (/\b(price|pricing|cost|costs|expensive|cheaper|discount|quote|quoted|invoice|refund|contract|complain|complaint|disappointed|unhappy|angry|terrible|crash\w*|broken|not working|bug|issue|problem|talk to (someone|a person|a human|your team)|speak (to|with) (someone|a person|a human)|real person|human|manager|call me|on a call|phone)\b/.test(last)) {
  if (cat !== 'stop') { cat = 'needs_human'; reason = reason && d.category === 'needs_human' ? reason : 'price, complaint or asks for a person'; }
}
return [{ json: { ...p, category: cat, reason, reply: cat === 'normal' ? String(d.reply || '') : '' } }];

const pick = (...names) => { for (const n of names) { try { return $(n); } catch (e) {} } throw new Error('Node not found: ' + names.join(' / ')); };
// Final status for the lead + log line
const p = pick('M: Parse').first().json;
const sent = String($json.query?.decision || '') === 'sent';
return [{ json: { id: p.lead_id, status: 'replied', next_action_at: '',
  log_action: sent ? 'message_reply_sent' : 'message_reply_skipped', log_details: p.name } }];

const pick = (...names) => { for (const n of names) { try { return $(n); } catch (e) {} } throw new Error('Node not found: ' + names.join(' / ')); };
const norm = v => String(v || '').toLowerCase().replace(/\b(mr|mrs|ms|miss|dr|prof)\.?\s+/g, '').replace(/\s+/g, ' ').trim();
const findLead = (q, leads) => { q = norm(q); if (!q) return null;
  return leads.find(l => norm(l.id) === q) ||
         leads.find(l => l.profile_url && (norm(l.profile_url) === q || q.includes(norm(l.profile_url)))) ||
         leads.find(l => norm(l.name) === q) ||
         leads.find(l => l.name && (q.includes(norm(l.name)) || norm(l.name).includes(q))) || null; };
// One control form: lead status changes, stop/do-not-contact, delete data, pause/resume
// (reads the fields by label keyword, so renamed labels still work)
const f0 = $input.first().json;
const get = re => { const e = Object.entries(f0).find(([k, v]) => re.test(k) && typeof v === 'string'); return e ? e[1] : ''; };
const action = String(get(/action/i) || Object.values(f0).find(v => typeof v === 'string' && /^(connection accepted|they replied|said no|delete their data|pause|resume)/i.test(v)) || '');
const leadText = get(/lead|name|profile/i);
const notes = String(get(/note/i) || '');
const leads = pick('C: Get Leads').all().map(i => i.json).filter(l => l.id);
const out = { update_lead: false, add_dnc: false, pause: '', alert: false, dnc_entry: '', dnc_reason: '' };
if (/^pause/i.test(action)) Object.assign(out, { pause: 'TRUE', alert: true, log_action: 'paused_manual', log_details: notes || 'warning / restriction seen' });
else if (/^resume/i.test(action)) Object.assign(out, { pause: 'FALSE', log_action: 'resumed', log_details: notes || 'resumed' });
else {
  const l = findLead(leadText, leads);
  if (!l) throw new Error('Lead not found in the Leads tab: ' + leadText);
  const row = { id: l.id, name: l.name, role: l.role, company: l.company, profile_url: l.profile_url, draft: l.draft,
                status: l.status, next_action_at: l.next_action_at };
  if (/^connection accepted/i.test(action)) row.status = 'connected';
  if (/^they replied/i.test(action)) { row.status = 'replied'; row.next_action_at = ''; }
  if (/^said no/i.test(action)) { row.status = 'do_not_contact'; row.next_action_at = '';
    Object.assign(out, { add_dnc: true, dnc_entry: l.profile_url || l.name, dnc_reason: 'said no / asked to stop' }); }
  if (/^delete their data/i.test(action)) {
    Object.assign(out, { add_dnc: true, dnc_entry: l.profile_url || l.name, dnc_reason: 'asked to delete their data' });
    Object.assign(row, { name: 'deleted', role: '', company: '', profile_url: '', draft: '', status: 'deleted', next_action_at: '' });
  }
  Object.assign(out, row, { update_lead: true, log_action: 'lead_' + row.status, log_details: row.id });
}
return [{ json: out }];

const pick = (...names) => { for (const n of names) { try { return $(n); } catch (e) {} } throw new Error('Node not found: ' + names.join(' / ')); };
// Today's summary from Logs
const s = pick('R: Get Settings').first().json;
if (String(s.daily_report).trim().toUpperCase() !== 'TRUE') return [];
const tz = s.timezone || 'Asia/Kolkata';
const today = DateTime.now().setZone(tz).toISODate();
const logs = pick('R: Get Logs').all().map(i => i.json).filter(l => l.time &&
  DateTime.fromISO(String(l.time)).setZone(tz).toISODate() === today);
const leads = pick('R: Get Leads').all().map(i => i.json).filter(l => l.id);
const count = a => logs.filter(l => l.action === a).length;
const rows = [
  ['New leads found', logs.filter(l => l.action === 'leads_found').reduce((n, l) => n + (parseInt(l.details) || 0), 0)],
  ['Outreach sent (requests / messages / follow-ups)', count('outreach_sent')],
  ['Outreach skipped', count('outreach_skipped')],
  ['Message replies sent', count('message_reply_sent')],
  ['Messages passed to a person', count('message_escalated')],
  ['People added to do-not-contact', count('message_stop') + count('lead_do_not_contact')],
  ['Posts approved / rejected', count('post_approved') + ' / ' + count('post_rejected')],
  ['Posts published', count('post_published')],
  ['Comments liked', count('comment_liked')],
  ['Comment replies posted', count('comment_replied')],
  ['Comments escalated / skipped', count('comment_escalated') + ' / ' + count('comment_skipped')],
  ['Rate limits (429)', count('rate_limited')],
  ['Pauses', count('paused_on_error') + count('paused_manual')],
];
const pipeline = ['new', 'request_sent', 'connected', 'messaged', 'followed_up', 'replied', 'do_not_contact']
  .map(st => st + ': ' + leads.filter(l => l.status === st).length).join(' · ');
const html = `<h3>LinkedIn automation — ${today}</h3>
<p>Status: <b>${String(s.paused).toUpperCase() === 'TRUE' ? 'PAUSED' : 'running'}</b></p>
<table cellpadding="6" style="border-collapse:collapse">${rows.map(r => `<tr><td style="border-bottom:1px solid #ddd">${r[0]}</td><td style="border-bottom:1px solid #ddd"><b>${r[1]}</b></td></tr>`).join('')}</table>
<p><b>Lead pipeline:</b> ${pipeline}</p><p>Every action is in the Logs tab.</p>`;
return [{ json: { html, subject: 'LinkedIn daily report — ' + today } }];
